/**
 ******************************************************************************
 * @file    test_msc_store.c
 * TEAM CODE (owner: Brendon - battery monitor and USB-C MSC) - written by the BJT2 team, not generated by STM32CubeMX.
 * @brief   Unit tests for the USB-MSC <-> SD backing-store manager.
 *
 * Owner: Brendon Bone (PD5b).
 *
 * Coverage: the bring-up state machine (ready/busy/rate-limited/error paths,
 * including an attempt at tick 0 and the best-effort wide-bus upgrade), the
 * bounded post-I/O idle wait on both the read and write paths (success,
 * SD failure, wedged-card timeout), capacity reporting with the enumeration
 * fallback, readiness mapping, and parameter validation throughout.
 ******************************************************************************
 */
#include "unity.h"
#include "msc_store.h"
#include "mock_sd.h"

#include <string.h>

/* Fallback geometry mirrors the CubeMX defaults in usbd_storage_if.c. */
#define FALLBACK_BLK_NBR  0x10000U
#define FALLBACK_BLK_SIZ  0x200U

static MSC_Store s_store;
static uint8_t   s_buf[512];

void setUp(void)
{
    MockSd_Reset();
    memset(&s_store, 0, sizeof(s_store));
    TEST_ASSERT_EQUAL(MSC_OK, MSC_Init(&s_store, MockSd_Iface(),
                                       FALLBACK_BLK_NBR, FALLBACK_BLK_SIZ));
}

void tearDown(void)
{
}

/* -------------------------------------------------------------------------- */
/* Initialisation                                                              */
/* -------------------------------------------------------------------------- */

static void test_init_rejects_bad_params(void)
{
    MSC_SdOps bad;

    TEST_ASSERT_EQUAL(MSC_BAD_PARAM,
                      MSC_Init(NULL, MockSd_Iface(), 1U, 1U));
    TEST_ASSERT_EQUAL(MSC_BAD_PARAM, MSC_Init(&s_store, NULL, 1U, 1U));

    memset(&bad, 0, sizeof(bad));   /* incomplete ops table */
    TEST_ASSERT_EQUAL(MSC_BAD_PARAM, MSC_Init(&s_store, &bad, 1U, 1U));
}

/* -------------------------------------------------------------------------- */
/* Bring-up poll                                                               */
/* -------------------------------------------------------------------------- */

static void test_poll_ready_card_is_left_alone(void)
{
    MockSd_SetState((int)MSC_CARD_READY);
    TEST_ASSERT_EQUAL(MSC_OK, MSC_Poll(&s_store, 0U));
    TEST_ASSERT_EQUAL_UINT32(0U, MockSd_InitCalls());
}

static void test_poll_busy_card_is_never_disturbed(void)
{
    /* e.g. the audio recorder mid-write: bring-up must not touch it. */
    MockSd_SetState((int)MSC_CARD_BUSY);
    TEST_ASSERT_EQUAL(MSC_BUSY, MSC_Poll(&s_store, 10000U));
    TEST_ASSERT_EQUAL_UINT32(0U, MockSd_InitCalls());
}

static void test_poll_brings_card_up_with_wide_bus(void)
{
    /* Card down; init succeeds and the 4-bit upgrade works. */
    TEST_ASSERT_EQUAL(MSC_OK, MSC_Poll(&s_store, 0U));
    TEST_ASSERT_EQUAL_UINT32(1U, MockSd_InitCalls());
    TEST_ASSERT_EQUAL_UINT32(1U, MockSd_WideBusCalls());
    TEST_ASSERT_EQUAL_UINT8(1U, MSC_WideBusActive(&s_store));
    TEST_ASSERT_EQUAL_UINT8(1U, MSC_IsReady(&s_store));
}

static void test_poll_wide_bus_failure_keeps_one_bit_mode(void)
{
    MockSd_FailWideBus(1);
    /* Best-effort: 1-bit mode is kept and the poll still succeeds. */
    TEST_ASSERT_EQUAL(MSC_OK, MSC_Poll(&s_store, 0U));
    TEST_ASSERT_EQUAL_UINT8(0U, MSC_WideBusActive(&s_store));
}

static void test_poll_init_failure_reports_error(void)
{
    MockSd_FailInit(1);
    TEST_ASSERT_EQUAL(MSC_ERROR, MSC_Poll(&s_store, 0U));
    TEST_ASSERT_EQUAL_UINT32(1U, MockSd_InitCalls());
    TEST_ASSERT_EQUAL_UINT32(0U, MockSd_WideBusCalls());
}

static void test_poll_rate_limits_retries_to_500ms(void)
{
    MockSd_FailInit(1);
    MockSd_InitBringsCardUp(0);

    TEST_ASSERT_EQUAL(MSC_ERROR, MSC_Poll(&s_store, 1000U));
    TEST_ASSERT_EQUAL(MSC_RATE_LIMITED, MSC_Poll(&s_store, 1250U));
    TEST_ASSERT_EQUAL(MSC_RATE_LIMITED, MSC_Poll(&s_store, 1499U));
    TEST_ASSERT_EQUAL_UINT32(1U, MockSd_InitCalls());

    TEST_ASSERT_EQUAL(MSC_ERROR, MSC_Poll(&s_store, 1500U));
    TEST_ASSERT_EQUAL_UINT32(2U, MockSd_InitCalls());
}

static void test_poll_rate_limit_applies_from_tick_zero(void)
{
    /* Fix over the demo code: a failed attempt AT tick 0 still arms the
     * rate limiter (the old "last try == 0" sentinel treated it as never
     * having tried, allowing an immediate hammering retry). */
    MockSd_FailInit(1);
    MockSd_InitBringsCardUp(0);

    TEST_ASSERT_EQUAL(MSC_ERROR, MSC_Poll(&s_store, 0U));
    TEST_ASSERT_EQUAL(MSC_RATE_LIMITED, MSC_Poll(&s_store, 100U));
    TEST_ASSERT_EQUAL_UINT32(1U, MockSd_InitCalls());
}

static void test_poll_rejects_null(void)
{
    TEST_ASSERT_EQUAL(MSC_BAD_PARAM, MSC_Poll(NULL, 0U));
}

/* -------------------------------------------------------------------------- */
/* Readiness                                                                   */
/* -------------------------------------------------------------------------- */

static void test_is_ready_maps_card_states(void)
{
    MockSd_SetState((int)MSC_CARD_READY);
    TEST_ASSERT_EQUAL_UINT8(1U, MSC_IsReady(&s_store));

    MockSd_SetState((int)MSC_CARD_BUSY);
    TEST_ASSERT_EQUAL_UINT8(0U, MSC_IsReady(&s_store));

    MockSd_SetState((int)MSC_CARD_NOT_READY);
    TEST_ASSERT_EQUAL_UINT8(0U, MSC_IsReady(&s_store));

    TEST_ASSERT_EQUAL_UINT8(0U, MSC_IsReady(NULL));
}

/* -------------------------------------------------------------------------- */
/* Block reads                                                                 */
/* -------------------------------------------------------------------------- */

static void test_read_waits_for_card_to_go_idle(void)
{
    MockSd_SetState((int)MSC_CARD_READY);
    MockSd_SetBusyPollsAfterIo(5U);   /* card programs for 5 polls, then idle */

    TEST_ASSERT_EQUAL(MSC_OK, MSC_ReadBlocks(&s_store, s_buf, 2048U, 4U));
    TEST_ASSERT_EQUAL_UINT32(1U, MockSd_ReadCalls());
    TEST_ASSERT_EQUAL_UINT32(2048U, MockSd_LastBlkAddr());
    TEST_ASSERT_EQUAL_UINT16(4U, MockSd_LastBlkLen());
    TEST_ASSERT_EQUAL_UINT32(6U, MockSd_GetStateCalls());   /* 5 busy + 1 idle */
}

static void test_read_rejects_bad_params(void)
{
    TEST_ASSERT_EQUAL(MSC_BAD_PARAM, MSC_ReadBlocks(NULL, s_buf, 0U, 1U));
    TEST_ASSERT_EQUAL(MSC_BAD_PARAM, MSC_ReadBlocks(&s_store, NULL, 0U, 1U));
    TEST_ASSERT_EQUAL(MSC_BAD_PARAM, MSC_ReadBlocks(&s_store, s_buf, 0U, 0U));
    TEST_ASSERT_EQUAL_UINT32(0U, MockSd_ReadCalls());
}

static void test_read_failure_reports_error_without_wait(void)
{
    MockSd_FailRead(1);
    TEST_ASSERT_EQUAL(MSC_ERROR, MSC_ReadBlocks(&s_store, s_buf, 0U, 1U));
    TEST_ASSERT_EQUAL_UINT32(0U, MockSd_GetStateCalls());
}

static void test_read_wedged_card_times_out(void)
{
    MockSd_SetState((int)MSC_CARD_READY);
    MockSd_SetBusyPollsAfterIo(MSC_WAIT_MAX_POLLS + 10U);

    TEST_ASSERT_EQUAL(MSC_TIMEOUT, MSC_ReadBlocks(&s_store, s_buf, 0U, 1U));
    TEST_ASSERT_EQUAL_UINT32(MSC_WAIT_MAX_POLLS, MockSd_GetStateCalls());
}

/* -------------------------------------------------------------------------- */
/* Block writes                                                                */
/* -------------------------------------------------------------------------- */

static void test_write_waits_for_card_to_go_idle(void)
{
    MockSd_SetState((int)MSC_CARD_READY);
    MockSd_SetBusyPollsAfterIo(3U);

    TEST_ASSERT_EQUAL(MSC_OK, MSC_WriteBlocks(&s_store, s_buf, 4096U, 8U));
    TEST_ASSERT_EQUAL_UINT32(1U, MockSd_WriteCalls());
    TEST_ASSERT_EQUAL_UINT32(4096U, MockSd_LastBlkAddr());
    TEST_ASSERT_EQUAL_UINT16(8U, MockSd_LastBlkLen());
    TEST_ASSERT_EQUAL_UINT32(4U, MockSd_GetStateCalls());
}

static void test_write_rejects_bad_params(void)
{
    TEST_ASSERT_EQUAL(MSC_BAD_PARAM, MSC_WriteBlocks(&s_store, NULL, 0U, 1U));
    TEST_ASSERT_EQUAL(MSC_BAD_PARAM, MSC_WriteBlocks(&s_store, s_buf, 0U, 0U));
    TEST_ASSERT_EQUAL_UINT32(0U, MockSd_WriteCalls());
}

static void test_write_failure_and_timeout(void)
{
    MockSd_FailWrite(1);
    TEST_ASSERT_EQUAL(MSC_ERROR, MSC_WriteBlocks(&s_store, s_buf, 0U, 1U));

    MockSd_FailWrite(0);
    MockSd_SetBusyPollsAfterIo(MSC_WAIT_MAX_POLLS + 1U);
    TEST_ASSERT_EQUAL(MSC_TIMEOUT, MSC_WriteBlocks(&s_store, s_buf, 0U, 1U));
}

/* -------------------------------------------------------------------------- */
/* Capacity reporting                                                          */
/* -------------------------------------------------------------------------- */

static void test_capacity_uses_true_geometry_when_ready(void)
{
    uint32_t num = 0U;
    uint16_t siz = 0U;

    MockSd_SetState((int)MSC_CARD_READY);
    MockSd_SetCapacity(15523840U, 512U);   /* 8 GB card */

    TEST_ASSERT_EQUAL(MSC_OK, MSC_GetCapacity(&s_store, &num, &siz));
    TEST_ASSERT_EQUAL_UINT32(15523840U, num);
    TEST_ASSERT_EQUAL_UINT16(512U, siz);
}

static void test_capacity_falls_back_when_card_not_ready(void)
{
    uint32_t num = 0U;
    uint16_t siz = 0U;

    MockSd_SetState((int)MSC_CARD_NOT_READY);
    TEST_ASSERT_EQUAL(MSC_FALLBACK, MSC_GetCapacity(&s_store, &num, &siz));
    TEST_ASSERT_EQUAL_UINT32(FALLBACK_BLK_NBR, num);
    TEST_ASSERT_EQUAL_UINT16(FALLBACK_BLK_SIZ, siz);
}

static void test_capacity_falls_back_when_query_fails(void)
{
    uint32_t num = 0U;
    uint16_t siz = 0U;

    MockSd_SetState((int)MSC_CARD_READY);
    MockSd_FailCapacity(1);
    TEST_ASSERT_EQUAL(MSC_FALLBACK, MSC_GetCapacity(&s_store, &num, &siz));
    TEST_ASSERT_EQUAL_UINT32(FALLBACK_BLK_NBR, num);
    TEST_ASSERT_EQUAL_UINT16(FALLBACK_BLK_SIZ, siz);
}

static void test_capacity_rejects_null_outputs(void)
{
    uint32_t num = 0U;
    uint16_t siz = 0U;

    TEST_ASSERT_EQUAL(MSC_BAD_PARAM, MSC_GetCapacity(&s_store, NULL, &siz));
    TEST_ASSERT_EQUAL(MSC_BAD_PARAM, MSC_GetCapacity(&s_store, &num, NULL));
    TEST_ASSERT_EQUAL(MSC_BAD_PARAM, MSC_GetCapacity(NULL, &num, &siz));
}

/* -------------------------------------------------------------------------- */
/* Runner                                                                      */
/* -------------------------------------------------------------------------- */

int main(void)
{
    UNITY_BEGIN();

    RUN_TEST(test_init_rejects_bad_params);

    RUN_TEST(test_poll_ready_card_is_left_alone);
    RUN_TEST(test_poll_busy_card_is_never_disturbed);
    RUN_TEST(test_poll_brings_card_up_with_wide_bus);
    RUN_TEST(test_poll_wide_bus_failure_keeps_one_bit_mode);
    RUN_TEST(test_poll_init_failure_reports_error);
    RUN_TEST(test_poll_rate_limits_retries_to_500ms);
    RUN_TEST(test_poll_rate_limit_applies_from_tick_zero);
    RUN_TEST(test_poll_rejects_null);

    RUN_TEST(test_is_ready_maps_card_states);

    RUN_TEST(test_read_waits_for_card_to_go_idle);
    RUN_TEST(test_read_rejects_bad_params);
    RUN_TEST(test_read_failure_reports_error_without_wait);
    RUN_TEST(test_read_wedged_card_times_out);

    RUN_TEST(test_write_waits_for_card_to_go_idle);
    RUN_TEST(test_write_rejects_bad_params);
    RUN_TEST(test_write_failure_and_timeout);

    RUN_TEST(test_capacity_uses_true_geometry_when_ready);
    RUN_TEST(test_capacity_falls_back_when_card_not_ready);
    RUN_TEST(test_capacity_falls_back_when_query_fails);
    RUN_TEST(test_capacity_rejects_null_outputs);

    return UNITY_END();
}
